-- Shorter bakery batches: 10 / 20 / 30 / 60 minutes / 2 / 4 hours.
-- Safe to run again. Only catalogue durations change; recipes keep their
-- ingredients, prices, XP and unlock levels. Existing queue timestamps,
-- including waiting and finished batches, are deliberately preserved.
-- Generated by the CLI; ordered after the existing bakery migration.
begin;

update public.arena_farm_bakery_recipes as r
set seconds = v.seconds
from (values
  ('bread', 600),
  ('berrytart', 1200),
  ('milkbun', 1800),
  ('carrotcake', 3600),
  ('pumpkinpie', 7200),
  ('cornbread', 14400)
) as v(id, seconds)
where r.id = v.id and r.seconds is distinct from v.seconds;

commit;
